contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256[] calldata winners, string[] calldata modelURIs, string[] calldata modelTypes, uint256[2][] calldata customAttributes) public payable {
        require(winners.length == c.winnersPerPeriod());
        require(modelURIs.length == winners.length);
        require(modelTypes.length == winners.length);
        require(customAttributes.length == winners.length);
        require(c.isAdmin(address(this)));

        c.addPoints(winners.length == 0 ? 0 : winners[0], 0);
        c.pickWinner(winners);

        uint256 before = c.getUnclaimedRewards(address(this));
        uint256 numRounds = c.roundId();

        c.claimRewards(modelURIs, modelTypes, customAttributes);

        uint256 afterClaim = c.getUnclaimedRewards(address(this));
        uint256 claimed = c.numRoundsClaimed(address(this));

        assert(afterClaim == 0 && claimed == numRounds && before <= numRounds);
    }

    receive() external payable {}
}

