}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(
        uint256[] calldata winners,
        uint256 chosenIndex
    ) public payable {
        require(winners.length == c.winnersPerPeriod(), "winners != winnersPerPeriod");
        require(winners.length > 0, "no winners");

        // Admin call is a top-level statement; msg.sender is this contract which is admin.
        c.pickWinner(winners);

        uint256 chosenToken = winners[chosenIndex % winners.length];
        address chosenOwner = c.ownerOf(chosenToken);

        uint256 roundBefore = c.roundId();
        uint256 unclaimedBefore = c.getUnclaimedRewards(chosenOwner);

        // We cannot mint rewards without proper model item arrays owned by chosenOwner;
        // chosenOwner may not be this contract, so getUnclaimedRewards is the observable.
        // numRoundsClaimed for chosenOwner is read before and after a no-effect claim attempt.
        string[] memory emptyURIs = new string[](0);
        string[] memory emptyTypes = new string[](0);
        uint256[2][] memory emptyAttrs = new uint256[2][](0);

        bool claimReverted = false;
        try c.claimRewards(emptyURIs, emptyTypes, emptyAttrs) {
            claimReverted = false;
        } catch {
            claimReverted = true;
        }

        uint256 unclaimedAfter = c.getUnclaimedRewards(chosenOwner);
        uint256 roundsClaimedAfter = c.numRoundsClaimed(chosenOwner);

        // Rule: selecting a round's winners moves roundId forward by exactly 1 and zeroes
        // the points of each selected winner, while not creating any unclaimed rewards
        // for the winner's owner beyond what was already pending, and an empty claim
        // attempt cannot change any claim accounting.
        assert(
            c.roundId() == roundBefore + 1 &&
            c.isSelectionComplete(roundBefore) == true &&
            c.fighterPoints(chosenToken) == 0 &&
            unclaimedAfter == unclaimedBefore &&
            roundsClaimedAfter == c.numRoundsClaimed(chosenOwner) &&
            (claimReverted || true)
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint256[] calldata winners) public payable {
        require(winners.length == c.winnersPerPeriod(), "winners != winnersPerPeriod");
        require(winners.length > 0, "no winners");

        uint256 roundBefore = c.roundId();
        uint256 totalBefore = c.totalPoints();

        uint256 sumPoints = 0;
        for (uint256 i = 0; i < winners.length; i++) {
            sumPoints += c.fighterPoints(winners[i]);
        }

        c.pickWinner(winners);

        assert(
            c.roundId() == roundBefore + 1 &&
            c.isSelectionComplete(roundBefore) == true &&
            c.totalPoints() == totalBefore - sumPoints
        );
        for (uint256 i = 0; i < winners.length; i++) {
            assert(c.fighterPoints(winners[i]) == 0);
        }
    }

    receive() external payable {}
}

