contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 tokenId, uint256 points) public payable {
        require(points > 0 && points <= 10**30);
        require(_delegatedOrSelf(address(this)));
        require(tokenId < 2**32);

        uint256 beforeTotal = c.totalPoints();
        uint256 beforeToken = c.fighterPoints(tokenId);

        (bool ok, bytes memory data) = address(c).call(abi.encodeWithSignature("addPoints(uint256,uint256)", tokenId, points));

        uint256 afterTotal = c.totalPoints();
        uint256 afterToken = c.fighterPoints(tokenId);

        assert(ok && afterToken == beforeToken + points && afterTotal == beforeTotal + points);
    }

    function _delegatedOrSelf(address a) internal pure returns (bool) {
        return a != address(0);
    }
}

