            // failure must not advance the round or change points
            assert(afterRound == beforeRound);
            assert(c.totalPoints() == beforeTotalPoints);
            assert(c.fighterPoints(w0) == beforeW0Points);
            assert(c.fighterPoints(w1) == beforeW1Points);
        } else {
            // success advances round by exactly one
            assert(afterRound == beforeRound + 1);
            // the recorded winner addresses for the consumed round are the owners of w0 and w1
            address owner0 = c.winnerAddresses(beforeRound, 0);
            address owner1 = c.winnerAddresses(beforeRound, 1);
            assert(owner0 != address(0));
            assert(owner1 != address(0));
            // selected points are zeroed and removed from totalPoints
            assert(c.fighterPoints(w0) == 0);
            assert(c.fighterPoints(w1) == 0);
            assert(c.totalPoints() == beforeTotalPoints - beforeW0Points - beforeW1Points);
            // selection for that round is recorded as complete
            assert(c.isSelectionComplete(beforeRound));
        }
    }

    receive() external payable {}
}

