contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public {
        uint256 roundBefore = c.roundId();
        uint32 prevClaimed = c.numRoundsClaimed(address(this));
        if (prevClaimed < roundBefore) {
            (bool ok,) = address(c).call(
                abi.encodeWithSignature(
                    "claimRewards(string[],string[],uint256[2][])",
                    new string[](0),
                    new string[](0),
                    new uint256[2][](0)
                )
            );
            require(ok, "claimRewards reverted");
        }
        uint32 postClaimed = c.numRoundsClaimed(address(this));
        uint256 roundAfter = c.roundId();
        assert(roundAfter == roundBefore);
        assert(uint256(postClaimed) - uint256(prevClaimed) == (prevClaimed < roundBefore ? roundBefore - prevClaimed : 0));
    }
}

