contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256[] calldata winners) public payable {
        uint256 wpp = c.winnersPerPeriod();
        require(winners.length == wpp, "wrong winners length");

        uint256 beforeRoundId = c.roundId();
        require(!c.isSelectionComplete(beforeRoundId), "round already complete");

        address[] memory expectedOwners = new address[](winners.length);
        for (uint256 i = 0; i < winners.length; i++) {
            expectedOwners[i] = c.ownerOf(winners[i]);
        }

        bool reverted;
        try c.pickWinner(winners) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(!reverted);
        assert(c.roundId() == beforeRoundId + 1);
        assert(c.isSelectionComplete(beforeRoundId));
        bool ownersMatch = true;
        for (uint256 i = 0; i < winners.length; i++) {
            if (c.winnerAddresses(beforeRoundId, i) != expectedOwners[i]) {
                ownersMatch = false;
            }
        }
        assert(ownersMatch);
    }
}

