        c.adjustAdminAccess(address(this), true);

        // Select winners for the current round; this test contract may appear as a winner.
        c.pickWinner(winners);

        // Read how many unclaimed rewards this test contract has. This is a view call nested in an assignment,
        // which is allowed because it does not change state.
        uint256 unclaimed = c.getUnclaimedRewards(address(this));

        // Prepare claim arrays sized to the number of unclaimed rewards.
        string[] memory modelURIs = new string[](unclaimed);
        string[] memory modelTypes = new string[](unclaimed);
        uint256[2][] memory customAttributes = new uint256[2][](unclaimed);
        for (uint256 i = 0; i < unclaimed; i++) {
            modelURIs[i] = "";
            modelTypes[i] = "";
            customAttributes[i] = [uint256(100), uint256(100)];
        }

        // Claim rewards. Top-level state-changing call.
        c.claimRewards(modelURIs, modelTypes, customAttributes);

        // Read the new unclaimed count. Top-level view call via c.getUnclaimedRewards? No, use an assignment.
        uint256 remaining = c.getUnclaimedRewards(address(this));

        assert(remaining == 0 || unclaimed == 0);
    }

    receive() external payable {}
}

