        require(newOwner != address(0), "newOwner must be nonzero");
        address currentOwner = c._ownerAddress();
        bool calledByOwner = (useOwner % 2 == 0);
        address caller = calledByOwner ? currentOwner : address(uint160(uint256(keccak256(abi.encode(newOwner, useOwner))) | 1));
        if (caller == currentOwner) {
