        bool reverted;
        if (calledByOwner) {
            c.transferOwnership(newOwner);
            reverted = false;
        } else {
            try c.transferOwnership(newOwner) {
                reverted = false;
            } catch {
                reverted = true;
            }
        }
        assert(reverted == !calledByOwner && c._ownerAddress() == (calledByOwner ? newOwner : currentOwner));
    }

    receive() external payable {}
}

