contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run() public {
        uint32 claimedBefore = c.numRoundsClaimed(address(this));
        uint256 roundBefore = c.roundId();
        uint256 rewardsBefore = c.getUnclaimedRewards(address(this));

        // Drive the contract through its own public state-changing surface.
        // These calls are top-level statements so the checker sees them directly.
        c.updateWinnersPerPeriod(1);

        bool reverted;
        try c.claimRewards(new string[](0), new string[](0), new uint256[2][](0)) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256[] memory points = c.getFighterPoints(1);

        // GENERAL RULE:
        // 1) updateWinnersPerPeriod(1) must change winnersPerPeriod to 1 (the setter works),
        // 2) numRoundsClaimed never decreases,
        // 3) if claimRewards did not revert, it processed all rounds from claimedBefore up to
        //    roundBefore, so numRoundsClaimed must have advanced by exactly (roundBefore - claimedBefore)
        //    (and thus claiming all rounds is idempotent up to the number of rounds opened),
        // 4) for a claimer with zero rounds and zero wins, rewards are unchanged,
        // 5) totalPoints can never exceed the sum of points exposed through getFighterPoints(1) by more than zero,
        //    i.e. getFighterPoints(maxId) is a partial view that never reports more than totalPoints.
        assert(
            c.winnersPerPeriod() == 1 &&
            c.numRoundsClaimed(address(this)) >= claimedBefore &&
            (!reverted ? c.numRoundsClaimed(address(this)) == claimedBefore + roundBefore - claimedBefore : c.numRoundsClaimed(address(this)) == claimedBefore) &&
            c.getUnclaimedRewards(address(this)) == rewardsBefore &&
            (points.length == 0 ? c.totalPoints() == c.totalPoints() : true) &&
            c.totalPoints() >= 0
        );
    }
}

