contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint256 tokenId1, uint256 points1, uint256 tokenId2, uint256 points2) public {
        c.addPoints(tokenId1, points1);
        c.addPoints(tokenId2, points2);

        uint256 total = c.totalPoints();
        uint256 expectedTotal = points1 + points2;

        assert(total == expectedTotal);

        uint256[] memory pts1 = c.getFighterPoints(tokenId1 + 1);
        uint256[] memory pts2 = c.getFighterPoints(tokenId2 + 1);

        bool consistent1 = (tokenId1 < pts1.length) && (pts1[tokenId1] == points1);
        bool consistent2 = (tokenId2 < pts2.length) && (pts2[tokenId2] == points2);

        assert(consistent1 && consistent2);
    }

    receive() external payable {}
}
